import json

from taf.sbts.oam.coam.admin import admin
from taf.gnb.oam.coam.vdu import vdu as du_admin

from taf.rfrl.l3_call.delta.exceptions import EmptyDeltaFileFound


class DeltaOperator:
    """
    Responsible for creating delta for recommissioning dynamically and performing it via admin API.
    DeltaOperator is able to create delta, save it to json or perform full delta recommissioning.
    """
    __MISSING_IMPLEMENTATION_ERROR_MSG = "{} class has missing implementation of {} method"

    def __init__(self, connection_alias, delta_id):
        self._delta_id = delta_id
        self._connection_alias = connection_alias

    def perform_delta_recommissioning(self, skip_parameter_relation_errors=False, should_activate=True):
        """
        Performs delta recommissioning via admin api with stored delta variable under admin instance.
        :param skip_parameter_relation_errors: Skip parameter relation errors.
        :type skip_parameter_relation_errors: boolean
        :param should_activate: Should automatically activate plan.
        :type should_activate: boolean
        """
        self._perform_delta_recommissioning(skip_parameter_relation_errors=skip_parameter_relation_errors,
                                            should_activate=should_activate)

    def add_parameter_to_delta(self, dist_name, parameter, value):
        """
        Adds parameter to delta variable stored under admin instance.
        :param dist_name: full dist name to Managed Object where parameter should be added.
        :type dist_name: str
        :param parameter: parameter name that should be added e.g. 'pMax'
        :type parameter: str
        :param value: value of parameter that should be added e.g. '370'
        :type value: str
        """
        self._add_parameter_to_delta(dist_name=dist_name, parameter=parameter, value=value)

    def remove_delta(self):
        """ Removes delta variable stored under admin instance. """
        self._remove_delta()

    def is_empty(self):
        """
        Checks if delta is empty
        As result of get_delta is str which looks like "[]" when empty,
        True will be returned when len(self._admin.get_delta(delta_id=self._delta_id)) is <= 2

        :returns: True if delta is empty, False if it is not
        """
        return self._is_empty()

    def _perform_delta_recommissioning(self, skip_parameter_relation_errors, should_activate):
        raise NotImplementedError(self.__MISSING_IMPLEMENTATION_ERROR_MSG.format(
            self.__class__.__name__,
            "_perform_delta_recommissioning"))

    def _add_parameter_to_delta(self, dist_name, parameter, value):
        raise NotImplementedError(self.__MISSING_IMPLEMENTATION_ERROR_MSG.format(
            self.__class__.__name__,
            "_add_parameter_to_delta"))

    def _remove_delta(self):
        raise NotImplementedError(self.__MISSING_IMPLEMENTATION_ERROR_MSG.format(
            self.__class__.__name__,
            "_remove_delta"))

    def _is_empty(self):
        raise NotImplementedError(self.__MISSING_IMPLEMENTATION_ERROR_MSG.format(
            self.__class__.__name__,
            "_is_empty"))


class ClassicalDeltaOperator(DeltaOperator):
    def __init__(self, connection_alias, delta_id):
        super(ClassicalDeltaOperator, self).__init__(connection_alias, delta_id)
        self._admin = admin()
        self._admin.create_delta(delta_id=self._delta_id)

    def _perform_delta_recommissioning(self, skip_parameter_relation_errors, should_activate):
        self._admin.perform_delta_recommissioning(delta_file=self._get_delta(),
                                                  skip_parameter_relation_errors=skip_parameter_relation_errors,
                                                  should_activate=should_activate,
                                                  timeout=250,
                                                  connection=self._connection_alias)

    def _add_parameter_to_delta(self, dist_name, parameter, value):
        self._admin.append_parameter_update_to_delta(dist_name=dist_name, parameter=parameter, value=value,
                                                     delta_id=self._delta_id)

    def _remove_delta(self):
        self._admin.remove_delta(delta_id=self._delta_id)

    def _is_empty(self):
        return True if len(self._admin.get_delta(delta_id=self._delta_id)) <= 2 else False

    def _get_delta(self):
        res = self._admin.get_delta(delta_id=self._delta_id)

        if len(res) <= 2:
            raise EmptyDeltaFileFound("Your delta is empty! Please consider adding some parameters, delta"
                                      " recommissioning should not be performed with empty file.")

        return res


class CloudDeltaOperator(DeltaOperator):
    def __init__(self, connection_alias, delta_id):
        super(CloudDeltaOperator, self).__init__(connection_alias, delta_id)
        self._admin = du_admin()
        self._delta = []

    def _perform_delta_recommissioning(self, skip_parameter_relation_errors, should_activate):
        self._admin.perform_delta_recommissioning(delta_file=json.dumps(self._delta),
                                                  wait_for_completion=True,
                                                  should_activate=should_activate,
                                                  vdu_connection=self._connection_alias)

    def _add_parameter_to_delta(self, dist_name, parameter, value):
        delta_parameters_item = {'parameterName': parameter,
                                 'operation': 'update',
                                 'value': value}

        for delta_item in self._delta:
            if delta_item['distName'] == dist_name:
                delta_item['parameters'].append(delta_parameters_item)
                break
        else:
            self._delta.append({'distName': dist_name,
                                'operation': 'update',
                                'parameters': [delta_parameters_item]})

    def _remove_delta(self):
        self._delta.clear()
